/**
 * PayPal escrow primitives built on the official PayPal Server SDK
 * (@paypal/paypal-server-sdk – generated by APIMatic from PayPal's OpenAPI specs).
 *
 * Escrow model:  Orders v2 intent=AUTHORIZE  → funds are held on the buyer's
 * account (authorization) but not moved. Each verified milestone triggers a
 * partial capture; the final milestone uses finalCapture=true which releases
 * any uncaptured remainder back to the buyer. A rejected delivery voids the
 * authorization.
 */
import { randomUUID } from 'node:crypto';
import {
  Client,
  Environment,
  OrdersController,
  PaymentsController,
  CheckoutPaymentIntent,
  ApiError,
} from '@paypal/paypal-server-sdk';
import { config } from '../config.js';

const cents = (n) => Math.round(n * 100);
const money = (c) => ({ currencyCode: 'USD', value: (c / 100).toFixed(2) });

let sdk;
function controllers() {
  if (!sdk) {
    const client = new Client({
      clientCredentialsAuthCredentials: {
        oAuthClientId: config.paypal.clientId,
        oAuthClientSecret: config.paypal.clientSecret,
      },
      timeout: 15000,
      environment: config.paypal.environment === 'live' ? Environment.Production : Environment.Sandbox,
    });
    sdk = { orders: new OrdersController(client), payments: new PaymentsController(client) };
  }
  return sdk;
}

export const paypalMode = () => config.paypal.mode; // 'sandbox' | 'live' | 'mock'

/** Normalise SDK errors into something readable for the audit log / UI. */
function wrap(err, op) {
  if (err instanceof ApiError) {
    const body = typeof err.body === 'string' ? safeJson(err.body) : err.result;
    const detail = body?.details?.[0];
    const why =
      [detail?.issue ?? body?.name ?? body?.error, detail?.description ?? body?.message ?? body?.error_description].filter(Boolean).join(' ') ||
      (err.statusCode === 401 ? 'authentication failed – check PAYPAL_CLIENT_ID / PAYPAL_CLIENT_SECRET and PAYPAL_ENVIRONMENT' : err.message);
    const msg = `${op} failed (${err.statusCode}): ${why}`;
    const e = new Error(msg);
    e.debugId = body?.debug_id;
    e.status = err.statusCode;
    return e;
  }
  return err;
}
const safeJson = (s) => {
  try {
    return JSON.parse(s);
  } catch {
    return { message: s };
  }
};

export async function createEscrowOrder(deal) {
  const s = deal.selected;
  const unitC = cents(s.unitPrice);
  const totalC = unitC * s.quantity;

  if (paypalMode() === 'mock') {
    return { orderId: `MOCK-ORDER-${randomUUID().slice(0, 8).toUpperCase()}`, status: 'CREATED', amount: totalC / 100 };
  }
  try {
    const { result } = await controllers().orders.createOrder({
      paypalRequestId: `create-${deal.id}-${randomUUID()}`,
      prefer: 'return=representation',
      body: {
        intent: CheckoutPaymentIntent.Authorize,
        purchaseUnits: [
          {
            referenceId: deal.id,
            customId: deal.id,
            description: `EscrowPilot PO ${deal.id} – ${s.vendorName}`.slice(0, 127),
            softDescriptor: 'ESCROWPILOT',
            amount: { ...money(totalC), breakdown: { itemTotal: money(totalC) } },
            items: [
              {
                name: s.name.slice(0, 127),
                sku: s.sku,
                quantity: String(s.quantity),
                unitAmount: money(unitC),
                category: 'PHYSICAL_GOODS',
              },
            ],
          },
        ],
      },
    });
    return { orderId: result.id, status: result.status, amount: totalC / 100 };
  } catch (e) {
    throw wrap(e, 'createOrder');
  }
}

export async function authorizeOrder(orderId) {
  if (paypalMode() === 'mock') {
    return {
      authorizationId: `MOCK-AUTH-${randomUUID().slice(0, 8).toUpperCase()}`,
      status: 'CREATED',
      expiresAt: new Date(Date.now() + 29 * 864e5).toISOString(),
      payerEmail: 'buyer@mock.example',
    };
  }
  try {
    const { result } = await controllers().orders.authorizeOrder({
      id: orderId,
      paypalRequestId: `auth-${orderId}`,
      prefer: 'return=representation',
      body: {},
    });
    const auth = result.purchaseUnits?.[0]?.payments?.authorizations?.[0];
    if (!auth) throw new Error(`Order ${orderId} returned no authorization (status ${result.status})`);
    return { authorizationId: auth.id, status: auth.status, expiresAt: auth.expirationTime, payerEmail: result.payer?.emailAddress };
  } catch (e) {
    throw wrap(e, 'authorizeOrder');
  }
}

/** Capture part (or the rest) of an authorization – one call per verified milestone. */
export async function captureMilestone({ authorizationId, amount, finalCapture, requestId, note }) {
  if (amount <= 0) return { captureId: null, status: 'SKIPPED', amount: 0 };
  if (paypalMode() === 'mock') {
    return { captureId: `MOCK-CAP-${randomUUID().slice(0, 8).toUpperCase()}`, status: 'COMPLETED', amount };
  }
  try {
    const { result } = await controllers().payments.captureAuthorizedPayment({
      authorizationId,
      paypalRequestId: requestId, // idempotency: retries never double-capture
      prefer: 'return=representation',
      body: { amount: money(cents(amount)), finalCapture, noteToPayer: note?.slice(0, 255) },
    });
    return { captureId: result.id, status: result.status, amount };
  } catch (e) {
    throw wrap(e, 'captureAuthorizedPayment');
  }
}

export async function voidAuthorization(authorizationId) {
  if (paypalMode() === 'mock') return { status: 'VOIDED' };
  try {
    await controllers().payments.voidPayment({ authorizationId, prefer: 'return=minimal' });
    return { status: 'VOIDED' };
  } catch (e) {
    throw wrap(e, 'voidPayment');
  }
}
